-- Read-only count/content comparison; run unchanged on source and candidate.
-- Credential columns are excluded; the nonsecret password-change flag is retained.
SELECT 'payments' AS table_name,count(*)::int AS row_count,md5(coalesce(string_agg(j::text,E'\n' ORDER BY j::text),'')) AS content_digest,now() AS checked_at FROM (SELECT (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHERE key !~* '(password|secret|token)' OR key='must_change_password') AS j FROM public."payments" t) q UNION ALL SELECT 'progress' AS table_name,count(*)::int AS row_count,md5(coalesce(string_agg(j::text,E'\n' ORDER BY j::text),'')) AS content_digest,now() AS checked_at FROM (SELECT (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHERE key !~* '(password|secret|token)' OR key='must_change_password') AS j FROM public."progress" t) q UNION ALL SELECT 'students' AS table_name,count(*)::int AS row_count,md5(coalesce(string_agg(j::text,E'\n' ORDER BY j::text),'')) AS content_digest,now() AS checked_at FROM (SELECT (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHERE key !~* '(password|secret|token)' OR key='must_change_password') AS j FROM public."students" t) q UNION ALL SELECT 'activities' AS table_name,count(*)::int AS row_count,md5(coalesce(string_agg(j::text,E'\n' ORDER BY j::text),'')) AS content_digest,now() AS checked_at FROM (SELECT (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHERE key !~* '(password|secret|token)' OR key='must_change_password') AS j FROM public."activities" t) q UNION ALL SELECT 'app_admins' AS table_name,count(*)::int AS row_count,md5(coalesce(string_agg(j::text,E'\n' ORDER BY j::text),'')) AS content_digest,now() AS checked_at FROM (SELECT (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHERE key !~* '(password|secret|token)' OR key='must_change_password') AS j FROM public."app_admins" t) q UNION ALL SELECT 'enrollments' AS table_name,count(*)::int AS row_count,md5(coalesce(string_agg(j::text,E'\n' ORDER BY j::text),'')) AS content_digest,now() AS checked_at FROM (SELECT (SELECT jsonb_object_agg(key,value) FROM jsonb_each(to_jsonb(t)) WHE